IF md5(pg_get_functiondef('combat_panel_private.create_offer(uuid,bigint,text,text,text,boolean,jsonb)'::regprocedure)) IS DISTINCT FROM '9dfe2da0b292de6370df2020c2166fe6' OR (SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid='combat_panel_private.create_offer(uuid,bigint,text,text,text,boolean,jsonb)'::regprocedure) IS DISTINCT FROM 'postgres' OR (SELECT proacl::text FROM pg_proc WHERE oid='combat_panel_private.create_offer(uuid,bigint,text,text,text,boolean,jsonb)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'qa_setup_baseline_pin_acl_drift';END IF;
