GRANT CREATE ON SCHEMA combat_panel_private TO postgres;
DO $environment_post$ BEGIN
IF NOT has_schema_privilege('postgres','combat_panel_private','USAGE') OR NOT has_schema_privilege('postgres','combat_panel_private','CREATE') OR (SELECT nspacl::text FROM pg_namespace WHERE nspname='combat_panel_private') IS DISTINCT FROM '{supabase_admin=UC/supabase_admin,postgres=UC/supabase_admin}' OR (SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='combat_panel_private') IS DISTINCT FROM 'supabase_admin' THEN RAISE EXCEPTION 'qa_environment_grant_attestation_failed';END IF;
