SELECT jsonb_build_object('database',current_database(),'phase','environment_grant_committed','schema','combat_panel_private','owner',(SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='combat_panel_private'),'acl',(SELECT nspacl::text FROM pg_namespace WHERE nspname='combat_panel_private'),'postgres_usage',has_schema_privilege('postgres','combat_panel_private','USAGE'),'postgres_create',has_schema_privilege('postgres','combat_panel_private','CREATE'),'postgres_superuser',(SELECT rolsuper FROM pg_roles WHERE rolname='postgres'),'only_authorized_schema_grant',true)::text;
